SELECT 
  FROM adv02_account
 WHERE adv02_company_id = #{p.companyId}
   AND UPPER(CONCAT(adv02_manage_cd, adv02_manage_nm)) LIKE UPPER(#{p.searchText})
 ORDER BY adv02_start_date, adv02_manage_cd
 LIMIT #{p.limit}
OFFSET #{p.offset}

SELECT 
  FROM adv02_account
 WHERE adv02_account_id = #{accountId}
   AND adv02_company_id = #{companyId}

SELECT COUNT(*)
  FROM adv02_account
 WHERE adv02_company_id = #{companyId}
   AND adv02_manage_cd  = #{manageCode}
   AND adv02_account_id != #{accountId}

SELECT COUNT(*)
  FROM adv02_account
 WHERE adv02_company_id = #{companyId}
   AND adv02_manage_cd  = #{manageCode}
